@RestController
@RequestMapping("/api/orders")
public class OrderController {

    @GetMapping("/{id}")
    public Order getOrder(@PathVariable Long id) {
        // Idempotent: calling this 10 times returns same order, no side effects
        return orderService.findById(id);
    }

    @PutMapping("/{id}")
    public Order updateOrder(@PathVariable Long id, @RequestBody Order order) {
        // Idempotent: setting status to SHIPPED 5 times still results in SHIPPED once
        order.setId(id);
        return orderService.update(order);
    }

    @PostMapping
    public Order createOrder(@RequestBody Order order) {
        // NOT idempotent: calling this 3 times creates 3 separate orders
        return orderService.create(order);
    }

    @DeleteMapping("/{id}")
    public void cancelOrder(@PathVariable Long id) {
        // Idempotent: deleting same order twice has same effect (it's gone)
        orderService.delete(id);
    }
}

