@RestController
@RequestMapping("/api/articles")
public class ArticleController {

    private final ArticleService service;

    public ArticleController(ArticleService service) {
        this.service = service;
    }

    // SAFE + idempotent: reading never changes state
    @GetMapping("/{id}")
    public Article get(@PathVariable Long id) {
        return service.findById(id);
    }

    // NOT safe, but idempotent: deleting twice leaves the same end state
    @DeleteMapping("/{id}")
    public ResponseEntity<Void> delete(@PathVariable Long id) {
        service.delete(id);                  // 2nd call: already gone, state unchanged
        return ResponseEntity.noContent().build();
    }

    // NOT safe and NOT idempotent: each POST creates a new article
    @PostMapping
    public ResponseEntity<Article> create(@RequestBody Article a) {
        return ResponseEntity.status(HttpStatus.CREATED).body(service.create(a));
    }
}
