@RestController
@RequestMapping("/api/payments")
public class PaymentController {
    private final PaymentService paymentService;
    private final RedisTemplate<String, PaymentResponse> redisTemplate;

    @PostMapping
    public ResponseEntity<PaymentResponse> createPayment(
            @RequestHeader("Idempotency-Key") String idempotencyKey,
            @RequestBody PaymentRequest request) {

        // Check if we've seen this idempotency key before
        var cached = redisTemplate.opsForValue().get(idempotencyKey);
        if (cached != null) {
            return ResponseEntity.ok(cached);  // Return cached result
        }

        // Process payment (first time seeing this key)
        var response = paymentService.processPayment(request);

        // Store result with 24-hour TTL
        redisTemplate.opsForValue().set(
            idempotencyKey, 
            response, 
            Duration.ofHours(24)
        );

        return ResponseEntity.status(HttpStatus.CREATED).body(response);
    }
}

