@RestController
@RequestMapping("/api/orders")
public class OrderController {

    @PutMapping("/{id}")
    public Order updateOrder(@PathVariable Long id, @RequestBody Order order) {
        var existing = orderRepository.findById(id)
            .orElseThrow(() -> new OrderNotFoundException(id));

        // Client must send the version they read
        if (!existing.getVersion().equals(order.getVersion())) {
            throw new OptimisticLockException("Order was modified by another user");
        }

        existing.setStatus(order.getStatus());
        return orderRepository.save(existing);  // Version auto-incremented
    }
}

@RestController
@RequestMapping("/api/payments")
public class PaymentController {
    private final PaymentService paymentService;
    private final RedisTemplate<String, String> redisTemplate;

    @PostMapping
    public ResponseEntity<PaymentResponse> processPayment(
            @RequestHeader("Idempotency-Key") String idempotencyKey,
            @RequestBody PaymentRequest request) {

        // Try to acquire lock for this idempotency key
        var lockKey = "payment:lock:" + idempotencyKey;
        var acquired = redisTemplate.opsForValue()
            .setIfAbsent(lockKey, "PROCESSING", Duration.ofMinutes(5));

        if (!acquired) {
            // Another request with same key is in progress
            return ResponseEntity.status(HttpStatus.CONFLICT)
                .body(new PaymentResponse("Payment in progress, try again in a moment"));
        }

        try {
            // Check if we already processed this payment
            var cached = redisTemplate.opsForValue().get("payment:result:" + idempotencyKey);
            if (cached != null) {
                return ResponseEntity.ok(parseResponse(cached));
            }

            // Process payment for the first time
            var result = paymentService.processPayment(request);

            // Store result with TTL
            redisTemplate.opsForValue().set(
                "payment:result:" + idempotencyKey,
                serializeResponse(result),
                Duration.ofHours(48)
            );

            return ResponseEntity.status(HttpStatus.CREATED).body(result);

        } finally {
            // Release lock
            redisTemplate.delete(lockKey);
        }
    }
}
